public abstract class Employee {
    private String name;

    public Employee(String name) { this.name = name; }

    public String getName() { return name; }

    public abstract double calculatePay();      // every Employee pays differently

    public void printPayslip() {                // shared by all employees
        System.out.printf("%-12s %10.2f%n", name, calculatePay());
    }
}

public class SalariedEmployee extends Employee {
    private double monthlySalary;

    public SalariedEmployee(String name, double monthlySalary) {
        super(name);
        this.monthlySalary = monthlySalary;
    }

    @Override
    public double calculatePay() { return monthlySalary; }
}

public class HourlyEmployee extends Employee {
    private double rate;
    private int hours;

    public HourlyEmployee(String name, double rate, int hours) {
        super(name);
        this.rate = rate;
        this.hours = hours;
    }

    @Override
    public double calculatePay() { return rate * hours; }
}

Employee[] staff = {
    new SalariedEmployee("Ana", 45000),
    new HourlyEmployee("Jess", 250, 160)
};

for (Employee e : staff) {
    e.printPayslip();
}
